import { useMemo, useState } from 'react';
import { JxButton } from '@jinx-ui/react';

type Status = 'active' | 'paused' | 'over';

type Project = {
  id: string;
  name: string;
  spent: number;
  quota: number;
  status: Status;
};

const STATUS_LABEL: Record<Status, string> = {
  active: 'Активен',
  paused: 'На паузе',
  over: 'Перерасход',
};

const STATUS_COLOR: Record<Status, string> = {
  active: 'var(--jx-color-success)',
  paused: 'var(--jx-color-text-muted)',
  over: 'var(--jx-color-danger)',
};

const ALL_STATUSES: Status[] = ['active', 'paused', 'over'];

const PROJECTS: Project[] = [
  { id: 'p1', name: 'Атлас (миграция витрин)', spent: 18400, quota: 40000, status: 'active' },
  { id: 'p2', name: 'Биллинг: тарифы v2', spent: 37200, quota: 40000, status: 'active' },
  { id: 'p3', name: 'Поисковый индекс', spent: 9100, quota: 25000, status: 'paused' },
  { id: 'p4', name: 'Мобильный онбординг', spent: 51000, quota: 45000, status: 'over' },
  { id: 'p5', name: 'Аналитика воронок', spent: 12750, quota: 30000, status: 'active' },
  { id: 'p6', name: 'Склад: интеграция 1С', spent: 28000, quota: 28000, status: 'active' },
  { id: 'p7', name: 'Антифрод-правила', spent: 4300, quota: 20000, status: 'paused' },
  { id: 'p8', name: 'Реплика отчётов', spent: 33900, quota: 31000, status: 'over' },
  { id: 'p9', name: 'Портал партнёров', spent: 6800, quota: 35000, status: 'active' },
  { id: 'p10', name: 'Шина событий', spent: 21500, quota: 26000, status: 'active' },
  { id: 'p11', name: 'Легаси-CRM: вывод', spent: 15200, quota: 18000, status: 'paused' },
  { id: 'p12', name: 'Нагрузочные стенды', spent: 47300, quota: 42000, status: 'over' },
];

const PAGE_SIZE = 5;

const RADIUS = 18;
const CIRCUMFERENCE = 2 * Math.PI * RADIUS;

function QuotaDonut({ percent, color }: { percent: number; color: string }) {
  const clamped = Math.max(0, Math.min(100, percent));
  return (
    <svg
      width={48}
      height={48}
      viewBox="0 0 48 48"
      role="img"
      aria-label={`Квота выбрана на ${clamped}%`}
      style={{ flexShrink: 0 }}
    >
      <circle
        cx={24}
        cy={24}
        r={RADIUS}
        fill="none"
        stroke="var(--jx-color-border)"
        strokeWidth={5}
      />
      <circle
        cx={24}
        cy={24}
        r={RADIUS}
        fill="none"
        stroke={color}
        strokeWidth={5}
        strokeLinecap="round"
        strokeDasharray={CIRCUMFERENCE}
        strokeDashoffset={CIRCUMFERENCE * (1 - clamped / 100)}
        transform="rotate(-90 24 24)"
      />
      <text
        x={24}
        y={24}
        textAnchor="middle"
        dominantBaseline="central"
        fontSize={11}
        fill="var(--jx-color-text)"
      >
        {clamped}
      </text>
    </svg>
  );
}

export default function ProjectSpendPanel() {
  const [selected, setSelected] = useState<Status[]>(ALL_STATUSES);
  const [page, setPage] = useState(0);

  const filtered = useMemo(
    () => PROJECTS.filter((project) => selected.includes(project.status)),
    [selected],
  );

  const pageCount = Math.max(1, Math.ceil(filtered.length / PAGE_SIZE));
  const currentPage = Math.min(page, pageCount - 1);
  const rows = filtered.slice(currentPage * PAGE_SIZE, currentPage * PAGE_SIZE + PAGE_SIZE);

  const toggleStatus = (status: Status) => {
    setPage(0);
    setSelected((prev) =>
      prev.includes(status) ? prev.filter((item) => item !== status) : [...prev, status],
    );
  };

  const resetFilters = () => {
    setPage(0);
    setSelected(ALL_STATUSES);
  };

  return (
    <section
      style={{
        display: 'flex',
        flexDirection: 'column',
        gap: 'var(--jx-space-4)',
        padding: 'var(--jx-space-5)',
        background: 'var(--jx-color-surface)',
        border: '1px solid var(--jx-color-border)',
        borderRadius: 'var(--jx-radius-lg)',
        color: 'var(--jx-color-text)',
      }}
    >
      <h2 style={{ margin: 0, fontSize: 'var(--jx-font-size-lg)' }}>Расход по проектам</h2>

      <div
        role="group"
        aria-label="Фильтры по статусу"
        style={{ display: 'flex', flexWrap: 'wrap', gap: 'var(--jx-space-2)' }}
      >
        {ALL_STATUSES.map((status) => {
          const isOn = selected.includes(status);
          return (
            <button
              key={status}
              type="button"
              aria-pressed={isOn}
              onClick={() => toggleStatus(status)}
              style={{
                display: 'inline-flex',
                alignItems: 'center',
                gap: 'var(--jx-space-2)',
                padding: 'var(--jx-space-1) var(--jx-space-3)',
                borderRadius: 'var(--jx-radius-full)',
                border: '1px solid var(--jx-color-border)',
                background: isOn ? 'var(--jx-color-surface-accent)' : 'transparent',
                color: isOn ? 'var(--jx-color-text)' : 'var(--jx-color-text-muted)',
                font: 'inherit',
                cursor: 'pointer',
              }}
            >
              <span
                aria-hidden="true"
                style={{
                  width: 8,
                  height: 8,
                  borderRadius: 'var(--jx-radius-full)',
                  background: STATUS_COLOR[status],
                }}
              />
              {STATUS_LABEL[status]}
              <span aria-hidden="true" style={{ color: 'var(--jx-color-text-muted)' }}>
                {isOn ? '×' : '+'}
              </span>
            </button>
          );
        })}
      </div>

      {filtered.length === 0 ? (
        <div
          style={{
            display: 'flex',
            flexDirection: 'column',
            alignItems: 'center',
            gap: 'var(--jx-space-3)',
            padding: 'var(--jx-space-6)',
            border: '1px dashed var(--jx-color-border)',
            borderRadius: 'var(--jx-radius-md)',
            textAlign: 'center',
          }}
        >
          <p style={{ margin: 0, color: 'var(--jx-color-text-muted)' }}>
            Ни один проект не подходит под выбранные статусы.
          </p>
          <JxButton variant="primary" onClick={resetFilters}>
            Сбросить фильтры
          </JxButton>
        </div>
      ) : (
        <>
          <ul
            style={{
              listStyle: 'none',
              margin: 0,
              padding: 0,
              display: 'flex',
              flexDirection: 'column',
              gap: 'var(--jx-space-2)',
            }}
          >
            {rows.map((project) => {
              const percent = Math.round((project.spent / project.quota) * 100);
              return (
                <li
                  key={project.id}
                  style={{
                    display: 'flex',
                    alignItems: 'center',
                    gap: 'var(--jx-space-3)',
                    padding: 'var(--jx-space-3)',
                    border: '1px solid var(--jx-color-border)',
                    borderRadius: 'var(--jx-radius-md)',
                  }}
                >
                  <QuotaDonut percent={percent} color={STATUS_COLOR[project.status]} />
                  <div style={{ flex: 1, minWidth: 0 }}>
                    <div
                      style={{
                        overflow: 'hidden',
                        textOverflow: 'ellipsis',
                        whiteSpace: 'nowrap',
                      }}
                    >
                      {project.name}
                    </div>
                    <div
                      style={{
                        color: 'var(--jx-color-text-muted)',
                        fontSize: 'var(--jx-font-size-sm)',
                      }}
                    >
                      {project.spent.toLocaleString('ru-RU')} из{' '}
                      {project.quota.toLocaleString('ru-RU')} — {percent}%
                    </div>
                  </div>
                  <span
                    style={{
                      padding: 'var(--jx-space-1) var(--jx-space-2)',
                      borderRadius: 'var(--jx-radius-full)',
                      border: `1px solid ${STATUS_COLOR[project.status]}`,
                      color: STATUS_COLOR[project.status],
                      fontSize: 'var(--jx-font-size-sm)',
                      whiteSpace: 'nowrap',
                    }}
                  >
                    {STATUS_LABEL[project.status]}
                  </span>
                </li>
              );
            })}
          </ul>

          <div
            style={{
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'space-between',
              gap: 'var(--jx-space-3)',
            }}
          >
            <span
              style={{
                color: 'var(--jx-color-text-muted)',
                fontSize: 'var(--jx-font-size-sm)',
              }}
              aria-live="polite"
            >
              Страница {currentPage + 1} из {pageCount} — {filtered.length} проектов
            </span>
            <div style={{ display: 'flex', gap: 'var(--jx-space-2)' }}>
              <JxButton
                disabled={currentPage === 0}
                onClick={() => setPage((prev) => Math.max(0, Math.min(prev, pageCount - 1) - 1))}
              >
                Назад
              </JxButton>
              <JxButton
                disabled={currentPage >= pageCount - 1}
                onClick={() => setPage((prev) => Math.min(pageCount - 1, prev + 1))}
              >
                Вперёд
              </JxButton>
            </div>
          </div>
        </>
      )}
    </section>
  );
}

